// Define a rectangle as an array of four vertices
// Each vertex is a variable with x and y properties
// Assume that the vertices are ordered clockwise or counterclockwise
class NEdge {
	constructor(x, y) {
		x = x || ~~random(width);
		y = y || ~~random(height);
