		const f = random() < 0.1 ? 1/3 : 3;
		w = h * f;

		const a = (noise((x+y)/(width+height)*100) - 0.5) * QUARTER_PI; // random(-QUARTER_PI, QUARTER_PI);
		this.pointsFromRect(x, y, w, h, a);

		this.x = x;
		this.y = y;
		this.w = w;
		this.h = h;
		this.a = a;

		let colors = ["darkred", "purple", "blue", "navy"]
		this.clr = random() < 0.1 ? random(["darkred", "purple"]) :
random(["blue", "navy"]);
