	pointsFromRect(cx, cy, w, h, a) {
		this.edges = [];
		this.edges.push({x: cx - w/2 * cos(a) - h/2 * sin(a), y: cy - w/2 * sin(a) + h/2 * cos(a)});
		this.edges.push({x: cx + w/2 * cos(a) - h/2 * sin(a), y: cy + w/2 * sin(a) + h/2 * cos(a)});
		this.edges.push({x: cx + w/2 * cos(a) + h/2 * sin(a), y: cy + w/2 * sin(a) - h/2 * cos(a)});
		this.edges.push({x: cx - w/2 * cos(a) + h/2 * sin(a), y: cy - w/2 * sin(a) - h/2 * cos(a)});
		// define top left and bottom right
		let minx = Infinity, maxx = -Infinity, miny = Infinity, maxy = -Infinity;
		for (let p of this.edges) {
			if (p.x < minx) minx = p.x;
			if (p.x > maxx) maxx = p.x;
			if (p.y < miny) miny = p.y;
			if (p.y > maxy) maxy = p.y;
		}
		this.tl = {x: minx, y: miny}
		this.tr = {x: maxx, y: maxy}
	}

	draw() {
		push();
		let clr = color(this.clr);
		clr.setAlpha(128)
		stroke(clr);
		strokeWeight(2);
		noStroke();
		clr.setAlpha(128)
		fill(clr);
		beginShape();
		for (let p of this.edges) {
			vertex(p.x, p.y);
		}
		endShape(CLOSE);
		pop();
	}

	// Define a function to get the edge vector between two vertices
	edge(v1, v2) {
		return {x: v2.x - v1.x, y: v2.y - v1.y};
	}

	// Define a function to get the perpendicular vector of an edge
	// Rotate it by 90 degrees counter-clockwise
	perpendicular(e) {
		return {x: -e.y, y: e.x};
	}

	// Define a function to get the dot product of two vectors
	dot(v1, v2) {
		return v1.x * v2.x + v1.y * v2.y;
	}

	// Define a function to check if a point is on the left of a line
	// The line is defined by an edge and a vertex on the edge
	// Return true if the point is on the left, false if on the right or on the line
	isLeft(e, v, p) {
		let perp = this.perpendicular(e); // Get the perpendicular vector of the edge
		let vec = this.edge(v, p); // Get the vector from the vertex to the point
		let d = this.dot(perp, vec); // Get the dot product of the two vectors
		return d > 0; // The sign of the dot product determines the side
	}

	// Define a function to check if two rectangles intersect
	// Return true if they do, false otherwise
	intersects(arr) {
		for (let i of arr) {
			if (this !== i && this.intersect(i)) return true;
		}
		return false;
	}

	isInner(other) {
